sql.if:
AND (
  ${pid} IS NULL
  OR (
    NOT EXISTS (SELECT 1 FROM project_member pmn
                WHERE pmn.workspace_id = #{workspaceId}
                  AND pmn.project_id = ${pid}
                  AND pmn.user_id = #{viewerId}
                  AND pmn.access = 'none')
    AND (
      COALESCE((SELECT wm.project_access_mode FROM workspace_member wm
                WHERE wm.workspace_id = #{workspaceId}
                  AND wm.user_id = #{viewerId}), 'all') != 'assigned'
      OR EXISTS (SELECT 1 FROM project_member pma
                 WHERE pma.workspace_id = #{workspaceId}
                   AND pma.project_id = ${pid}
                   AND pma.user_id = #{viewerId}
                   AND pma.access IN ('write', 'read'))
    )
  )
)

mapper.select:
SELECT x.entity_type, x.id, x.at, x.entity_id, x.entity_title, x.project_id, x.project_name,
       x.action, x.detail, x.actor_name
  FROM () x

    AND x.entity_type = #{type}


 ORDER BY x.at DESC, x.sort_id DESC, x.id DESC
 LIMIT #{limit} OFFSET #{offset}
